xpath.script:
(function() {
    var STORAGE_KEY = 'dimsop-theme';
    function applyTheme(theme) {
        document.documentElement.setAttribute('data-theme', theme);
        try { localStorage.setItem(STORAGE_KEY, theme); } catch(e) {}
        var icon = document.querySelector('#dimsop-dark-toggle i');
        if (icon) icon.className = theme === 'dark' ? 'fa fa-sun-o' : 'fa fa-moon-o';
    }
    try {
        var t = localStorage.getItem(STORAGE_KEY);
        applyTheme(t === 'dark' ? 'dark' : 'light');
    } catch(e) { applyTheme('light'); }
    document.addEventListener('click', function(e) {
        var btn = e.target.closest('#dimsop-dark-toggle');
        if (!btn) return;
        var current = document.documentElement.getAttribute('data-theme');
        applyTheme(current === 'dark' ? 'light' : 'dark');
    });

    // Contadores de impacto: animar al entrar en viewport
    function animateCounter(el) {
        var target = parseInt(el.getAttribute('data-target'), 10) || 0;
        var duration = 1800;
        var start = performance.now();
        function frame(now) {
            var progress = Math.min((now - start) / duration, 1);
            var eased = 1 - Math.pow(1 - progress, 3);
            el.textContent = '+' + Math.floor(eased * target);
            if (progress < 1) { requestAnimationFrame(frame); }
            else { el.textContent = '+' + target; }
        }
        requestAnimationFrame(frame);
    }
    function initCounters() {
        var counters = document.querySelectorAll('.dimsop-counter-num');
        if (!counters.length || !('IntersectionObserver' in window)) return;
        var observer = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
                if (entry.isIntersecting) { animateCounter(entry.target); }
                else { entry.target.textContent = '+0'; }
            });
        }, { threshold: 0.3 });
        counters.forEach(function(c) { observer.observe(c); });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCounters);
    } else {
        initCounters();
    }
})();
